TIER_TO_LEAGUE = {0: 'kbo3', 1: 'kbo2', 2: 'kbo1'}


def tiers_to_leagues(apps, schema_editor):
    """예전 소속(0 육성군·1 2군·2 1군) → 리그 코드. 프로 선수의 소속 구단은 응원 팀으로 채운다."""
    Player = apps.get_model('community', 'RookiePlayer')
    for p in Player.objects.all():
        p.league = TIER_TO_LEAGUE.get(p.tier, 'kbo3')
        p.club = p.club or p.team
        p.age = 20 if p.age == 12 else p.age
        p.grade = 0
        p.save(update_fields=['league', 'club', 'age', 'grade'])


def int_leagues_to_codes(apps, schema_editor):
    for model in ('RookieSeasonStat', 'RookieGame'):
        M = apps.get_model('community', model)
        for old, new in (('0', 'kbo3'), ('1', 'kbo2'), ('2', 'kbo1')):
            M.objects.filter(league=old).update(league=new)


